import{t as e}from"./jsx-runtime-lw2jiZar.js";import{I as t,L as n,M as r,N as i,O as a,P as o,k as s}from"./shared-pB8LFUv2.js";import{t as c}from"./route-DOtsYfNV.js";import{P as l}from"./index-J3P0holD.js";var u=e();function d(){return(0,u.jsxs)(i,{children:[(0,u.jsx)(r,{variant:`project`,chip:`ГЛАВА 2 · КАРТА ОБУЧЕНИЯ`,title:`От Console Planner к надёжному приложению`,intro:`Продолжите знакомый планировщик задач: разберётесь в устройстве функций и ошибок, разделите код на модули, сохраните задачи между запусками и постепенно превратите словари в полноценные объекты. В конце у вас будет проверенный Persistent Planner, который можно запустить по инструкции.`,tags:[{icon:(0,u.jsx)(l,{size:14}),label:`занятия 21–44 · 43 шага`},{icon:(0,u.jsx)(c,{size:14}),label:`один проект · от функций до тестов`}]}),(0,u.jsxs)(`section`,{className:`rich-section learning-roadmap-preview`,children:[(0,u.jsx)(`div`,{className:`rich-section-title`,children:(0,u.jsx)(`h2`,{children:`Четыре шага к Persistent Planner`})}),(0,u.jsx)(a,{children:`Вы не начинаете новый проект с нуля. На каждом этапе знакомый Planner получает новую возможность, а вы понимаете, какую задачу решает каждый инструмент Python.`}),(0,u.jsxs)(n,{children:[(0,u.jsx)(t,{badge:`БЛОК 5`,title:`Управляйте поведением программы`,children:`Уточните контракты функций и передачу состояния, свяжите команды с обработчиками и научитесь наблюдать за работой функций без изменения их логики.`}),(0,u.jsx)(t,{badge:`БЛОК 6`,badgeTone:`float`,title:`Разложите код и сохраните данные`,children:`Разделите CLI, правила и хранение, научитесь разбирать ошибки и подключите JSON так, чтобы задачи переживали перезапуск.`}),(0,u.jsx)(t,{badge:`БЛОК 7`,badgeTone:`str`,title:`Создайте модель Task`,children:`Перенесите состояние задачи в класс, добавьте понятное поведение и подготовьте объект к обмену данными с прежним форматом JSON.`}),(0,u.jsx)(t,{badge:`БЛОК 8`,title:`Соберите и проверьте приложение`,children:`Подключите Task к Planner, выделите сервис и хранилище, защитите правила тестами и подготовьте проект к передаче.`})]})]}),(0,u.jsxs)(o,{number:`01`,title:`Блок 5 · Наведите порядок в функциях`,children:[(0,u.jsx)(a,{children:`Начнём с работающего Console Planner и сделаем его поведение прозрачнее. Уточним, какие данные принимает каждая функция и кто отвечает за состояние списка, затем применим callbacks и обёртку к уже знакомым операциям.`}),(0,u.jsx)(s,{variant:`connected`,items:[{title:`21 · Возвращаемся к Console Planner`,description:`Проверите реальные команды и проследите путь задачи через существующий код. Зафиксируете, что уже работает и какие части проекта предстоит улучшить, не переписывая готовые функции ради упражнения.`},{title:`22 · Функция: вход, правило и результат`,description:`Разделите обязанности обработчиков команд и добавите недостающие действия для списка и статистики. Сможете отличить значение, которое функция получает, от вывода, который она показывает.`},{title:`23 · Аргументы и значения по умолчанию`,description:`Уточните вызовы create_task и её пользователей. Настроите единый договор параметров и проверите, что существующие команды получают ожидаемые значения.`},{title:`24 · Область видимости и ссылки`,description:`Проследите, где создаётся имя и когда меняется сам список или вложенное значение. Это поможет не путать новую ссылку с изменением общего состояния Planner.`},{title:`24.1 · Состояние одного запуска`,description:`Передадите список задач в run явно и зададите безопасное поведение для нового запуска. Проверите, что два запуска не делят состояние случайно, а переданный список сохраняет изменения.`},{title:`25 · *args, **kwargs и распаковка`,description:`Разберёте сбор аргументов и их передачу дальше, увидите ошибки несовпадающих вызовов. Поймёте, когда forwarding сохраняет контракт функции, а когда только скрывает его.`},{title:`26 · Функция как значение и таблица команд`,description:`Соберёте существующие обработчики в таблицу команд. Убедитесь, что при создании таблицы функции не запускаются и неизвестная команда не меняет задачи.`},{title:`26.1 · Вложенные функции и замыкания`,description:`Создадите два независимо настроенных callback и проследите, какие значения каждая функция сохраняет из внешней области. Поймёте, как настройка отличается от общего изменяемого состояния.`},{title:`27 · Диагностическая обёртка`,description:`Обернёте существующую format_task наблюдением за вызовом, сохранив её аргументы и результат. Увидите, как добавить диагностику отдельно от основного поведения.`},{title:`27.1 · Декоратор и запись @`,description:`Сопоставите ручную обёртку с синтаксисом @ и разберёте, что меняется при преобразовании функции. Найдёте потерянный return и поймёте, почему декорировать всё приложение не нужно.`}]}),(0,u.jsxs)(n,{children:[(0,u.jsx)(t,{badge:`функции`,title:`Понимаете путь данных`,children:`Видите, что функция получает, какое правило выполняет и что возвращает. Сможете менять обработчик, не ломая договор его вызова.`}),(0,u.jsx)(t,{badge:`состояние`,badgeTone:`float`,title:`Знаете, кто владеет списком`,children:`Передаёте данные запуска явно и различаете независимую задачу со ссылками и случайное совместное изменение.`}),(0,u.jsx)(t,{badge:`команды`,badgeTone:`str`,title:`Управляете обработчиками осознанно`,children:`Используете функции как значения и добавляете диагностику вокруг знакомого поведения без скрытого запуска операций.`})]})]}),(0,u.jsxs)(o,{number:`02`,title:`Блок 6 · Сделайте ошибки и хранение предсказуемыми`,children:[(0,u.jsx)(a,{children:`Теперь подготовим Planner к росту и перезапуску. Разберём, где возникает отказ, отделим приложение от запуска и подключим JSON поэтапно — с проверкой восстановленных данных и безопасной реакцией на проблемы файла.`}),(0,u.jsx)(s,{variant:`connected`,items:[{title:`28 · Исключение и traceback своей программы`,description:`Проследите ошибочный вызов в собственном Planner и найдёте строку, где возникла проблема. Различите место возникновения и место, где программа может обработать ожидаемый отказ.`},{title:`29 · Конкретный try/except и общий ввод`,description:`Уберёте повторяющиеся циклы числового ввода в общий read_int. Сохраните отдельные диапазоны и сообщения для приоритета и id, не скрывая неожиданные ошибки.`},{title:`30 · raise, else, finally и правила данных`,description:`Перенесёте проверку неверных значений к границе создания задачи. Проверите, что ошибочный приоритет отклоняется до добавления или изменения записи.`},{title:`30.1 · Собственная ошибка и поиск задачи`,description:`Добавите get_task и TaskNotFoundError для обязательного получения по id. Научитесь отличать отсутствие задачи от некорректного действия и сохранять состояние при отказе.`},{title:`31 · Модули и безопасный импорт`,description:`Вынесете существующие правила и операции в отдельные файлы, настроите импорты и защитите точку запуска. Проверите, что импорт модуля не запускает меню.`},{title:`32 · Пакет app и направление импортов`,description:`Соберёте модули в пакет app и запустите приложение из корня командой python -m. Разберётесь, почему нижние модули не должны импортировать main.`},{title:`33 · CLI отдельно от сборки`,description:`Перенесёте ввод, вывод и обработчики в app.cli, оставив app.main выбор состояния и запуск. Явная передача списка покажет, кто владеет задачами.`},{title:`34 · Файл как ресурс`,description:`Поработаете с путями, режимами чтения и записи, with и UTF-8 на безопасном файле. Поймёте, как управлять файлом и почему закрытие ресурса должно быть гарантировано.`},{title:`34.1 · JSON настоящих задач`,description:`Преобразуете задачи своего Planner в JSON и обратно, сохранив поля и типы. Подготовите слой хранения, но пока не будете обещать сохранение между запусками.`},{title:`35 · Загрузка и сохранение после изменения`,description:`Подключите загрузку при запуске и сохранение после изменения. Перезапустите приложение и подтвердите, что созданная задача восстановилась из файла.`},{title:`35.1 · Проверка восстановленного состояния`,description:`Проверите весь снимок JSON: форму записи, типы, диапазоны и уникальность id. Некорректный файл будет обнаружен, а не молча заменён пустым списком.`},{title:`35.2 · Ошибки хранения и сохранность данных`,description:`Разберёте отсутствие файла, повреждённый JSON и проблемы доступа или записи. Настроите честный StorageError и проверите, что отказ не приводит к тихой потере данных.`}]}),(0,u.jsxs)(n,{children:[(0,u.jsx)(t,{badge:`ошибки`,title:`Отказ имеет понятную границу`,children:`Обрабатываете ожидаемые проблемы конкретно, а traceback помогает найти дефект, вместо того чтобы скрывать его широким except.`}),(0,u.jsx)(t,{badge:`структура`,badgeTone:`float`,title:`Импорт не запускает приложение`,children:`CLI, сборка и правила разнесены по модулям с понятным направлением зависимостей и одним способом запуска.`}),(0,u.jsx)(t,{badge:`JSON`,badgeTone:`str`,title:`Задачи переживают перезапуск`,children:`Planner загружает проверенные данные и сохраняет изменения. Ошибка файла не превращается в молчаливый сброс задач.`})]})]}),(0,u.jsxs)(o,{number:`03`,title:`Блок 7 · Представьте задачу объектом`,children:[(0,u.jsx)(a,{children:`Когда проект уже разделён, рассмотрим, что дают объекты. Построим Task сначала обычным классом, добавим поведение и безопасное представление, а затем осмысленно заменим шаблонный код dataclass — сохранив совместимость данных.`}),(0,u.jsx)(s,{variant:`connected`,items:[{title:`36 · Класс, объект, __init__ и self`,description:`Создадите объекты и проследите, как __init__ задаёт их начальное состояние, а self указывает на конкретный экземпляр. На маленьком примере увидите, когда класс полезнее словаря.`},{title:`36.1 · Обычная Task в проекте`,description:`Добавите первую модель Task в app.models и проверите её поля и правила создания. Существующие словарные данные пока продолжат работать в CLI и JSON.`},{title:`36.2 · Экземпляр и общие ссылки`,description:`Сравните поля экземпляра, атрибут класса и общие ссылки. Найдёте ошибку с общей изменяемой коллекцией и проверите независимость задач.`},{title:`37 · Методы и управляемое изменение`,description:`Добавите в Task методы завершения, переименования и смены приоритета. Проверите, что неверное значение отклоняется до изменения объекта.`},{title:`37.1 · Представление и вычисляемое свойство`,description:`Настроите понятное строковое представление и вычисляемый status_label. Увидите, как статус следует за состоянием, не храня дублирующее поле.`},{title:`37.2 · Task на границе словаря`,description:`Реализуете преобразование Task в словарь и обратно на записи собственного Planner. Сверите полный round trip и убедитесь, что поля не теряются.`},{title:`38 · Dataclass и управляемые поля`,description:`Замените шаблонный конструктор той же Task на dataclass. Сравните поведение до и после и сохраните проверки и методы модели.`},{title:`38.1 · Независимые tags и совместимость`,description:`Добавите задачам независимые tags через безопасное значение по умолчанию. Проверите копирование коллекций и совместимость старых JSON-записей.`},{title:`38.2 · Композиция и выбор формы`,description:`Рассмотрите, как небольшие объекты могут сотрудничать, и объясните границы модели. Подготовите архитектурный выбор к переносу Task в существующий Planner.`}]}),(0,u.jsxs)(n,{children:[(0,u.jsx)(t,{badge:`модель`,title:`Задача хранит своё состояние`,children:`Создаёте экземпляры Task с проверяемыми полями и понимаете роль конструктора и self.`}),(0,u.jsx)(t,{badge:`поведение`,badgeTone:`float`,title:`Изменения проходят через понятные правила`,children:`Используете методы и свойства для безопасных переходов, не дублируя состояние и не меняя объект при отказе.`}),(0,u.jsx)(t,{badge:`совместимость`,badgeTone:`str`,title:`Объект дружит с прежним JSON`,children:`Преобразуете Task в запись и обратно, добавляете независимые tags и проверяете старый формат данных.`})]})]}),(0,u.jsxs)(o,{number:`04`,title:`Блок 8 · Соберите проверенный Persistent Planner`,children:[(0,u.jsx)(a,{children:`Финальный этап объединит готовые части. Подключите Task к рабочим операциям, заменяемое хранилище и единый PlannerService, затем проверите команды, данные и инструкции так, как это сделает другой пользователь проекта.`}),(0,u.jsx)(s,{variant:`connected`,items:[{title:`39 · Task в существующем Planner`,description:`Переведёте рабочие операции и отображение на Task, сохранив прежние пользовательские команды и JSON. Убедитесь, что модель встроилась в приложение, а не стала отдельным примером.`},{title:`39.1 · JsonStorage вокруг хранения`,description:`Соберёте чтение и запись в JsonStorage с явным путём и актуальными данными на каждое действие. Проверите, что прежний постоянный список больше не расходится с файлом.`},{title:`40 · MemoryStorage и общий договор`,description:`Добавите альтернативное хранилище в памяти и сравните его с JsonStorage через одинаковые операции. Увидите, что можно заменить способ хранения, сохранив договор приложения.`},{title:`40.1 · PlannerService и чтение`,description:`Перенесёте список, получение, поиск и статистику в PlannerService. Согласуете результаты чтения, чтобы CLI не обращался к файлам напрямую.`},{title:`40.2 · Изменения и тонкий CLI`,description:`Завершите передачу добавления, завершения и удаления в единый сервис. Соберёте зависимости в одном месте и оставите CLI ответственным за общение с пользователем.`},{title:`41 · Первые тесты через pytest`,description:`Напишете первые проверки модели, MemoryStorage и операций сервиса по схеме Arrange–Act–Assert. Научитесь читать падение теста и находить нарушенный договор.`},{title:`41.1 · Свежие fixtures и параметризация`,description:`Уберёте повтор подготовки и проверите варианты одного правила отдельными случаями. Убедитесь, что тесты получают независимые данные и не влияют друг на друга.`},{title:`41.2 · Файловая интеграция через tmp_path`,description:`Проверите реальный JsonStorage на временном пути: старые записи, tags, восстановление и ошибки. Тесты подтвердят файловый контракт, не затрагивая рабочие задачи.`},{title:`42 · SOLID и проверяемая CLI-граница`,description:`Отделите обработку одной команды от цикла ввода и вывода. Поймёте SOLID через конкретные обязанности и подготовите CLI к проверке без ручной работы в терминале.`},{title:`42.1 · Регрессия команд и сохранений`,description:`Добавите проверки вывода, состояния, сохранений и безопасного импорта. Подтвердите, что изменения архитектуры не сломали знакомые команды Planner.`},{title:`43 · Сквозная приёмка проекта`,description:`Пройдёте путь пользователя через добавление, чтение, поиск, завершение, удаление и повторный запуск. Найденный дефект закрепите тестом и проверите весь накопленный результат.`},{title:`44 · README и передача проекта`,description:`Проверите зависимости, запуск, тесты и инструкцию в чистой копии репозитория. Подготовите README и выпуск, который другой человек сможет воспроизвести и понять.`}]}),(0,u.jsxs)(n,{children:[(0,u.jsx)(t,{badge:`проект`,title:`Одна модель и один сервис для команд`,children:`CLI использует PlannerService, а сервис работает с Task и выбранным хранилищем без дублирования бизнес-правил.`}),(0,u.jsx)(t,{badge:`проверки`,badgeTone:`float`,title:`Правила защищены тестами`,children:`Автоматически проверяете модель, оба вида хранения, сервис и CLI, включая ошибочные сценарии и независимые данные.`}),(0,u.jsx)(t,{badge:`готовность`,badgeTone:`str`,title:`Проект можно передать и запустить`,children:`Persistent Planner сохраняет задачи, проходит приёмку, имеет понятный README и воспроизводится из чистой копии.`})]})]})]})}export{d as LearningRoadmap};